    unknown_unknown = jnp.sum(unseen_counts * (unseen_counts - 1.), axis=1) / jnp.maximum(num_unseen * (num_unseen - 1.), 1.)
    partner_pair = jnp.where(seen[None, :, None] & seen[None, None, :], same_hyp.astype(jnp.float32),
                           jnp.where(seen[None, :, None], known_unknown[:, :, None],
                                     jnp.where(seen[None, None, :], known_unknown[:, None, :], unknown_unknown[:, None, None])))
    improvement = (new_dist_pair == 1).astype(jnp.float32) - (old_dist == 1).astype(jnp.float32)
    improvement = improvement - 0.035 * (new_dist_pair - old_dist)
    evidence_delta = jnp.einsum('bij,ij->b', partner_pair, improvement) / 2
    log_evidence = jnp.where(reset, 0., memory['log_evidence'])
    log_evidence = jnp.clip(log_evidence + jnp.where(partner_move, 2.0 * evidence_delta, 0.), -6., 6.)
    w, pair, marginal, same = beliefs(obs, known, log_evidence)
    dist = jnp.abs(pos[:, None, :] - pos[None, :, :]).sum(-1)
    adj = (dist == 1).astype(jnp.float32)
    edges = (pair * adj).sum() / 2
    solved = jnp.einsum('bij,ij->b', same.astype(jnp.float32), adj) >= 11.9
    p_solved = (w * solved).sum()

    entropy = -jnp.sum(marginal * jnp.log(jnp.maximum(marginal, 1e-8)), axis=1)
    # New evidence matters most on uncertain cards bordering remembered colors.
    known_near = (adj * (known >= 0)[None, :]).sum(1)
    voi = observation_values(pos, features[:9, 8] > 0, w, pair, marginal, same)
    inspect_score = voi + entropy * (0.15 + 0.015 * known_near + 0.025 * partner_moved) - 0.0002 * jnp.arange(9)
    inspect = 1 + jnp.argmax(jnp.where(obs.legal_actions[1:10], inspect_score, -1e9))
    inspect = jnp.where(obs.legal_actions[1067] & (p_solved > 0.85), 1067, inspect)

    cells = jnp.stack((jnp.arange(81) // 9, jnp.arange(81) % 9), axis=1)
    locked = features[:9, 8] > 0
    hint_revealed = jnp.any(features[9:, 3:6] > 0, axis=1)
    remaining = jnp.sum(jnp.where(features[9:, 8] > 0, 0, jnp.where(hint_revealed, 1, 2)))
    planning_enabled = (remaining > 1) & (jnp.sum(known >= 0) >= 4)
    move, planned = plan_move(pos, locked, pair, obs.legal_actions[10:739], planning_enabled)
    planned_card = jnp.where(reset, -1, memory['planned_card'])
    planned_card = jnp.where(active & (phase == 2), planned, planned_card)

    hints = features[9:, 3:6].astype(jnp.float32)
    correct = hints @ marginal.T
    same_degree = jnp.sum(pair * adj, axis=1)
    # Lock a plausible anchor already belonging to a group, using a correct hint.
    locked = features[:9, 8] > 0
    # Two distant locked cards of one color may make that color impossible.
    lock_conflict = jnp.sum(pair * locked[None, :] * jnp.maximum(dist - 2, 0), axis=1)
    anchor_support = jnp.sum(pair * locked[None, :] * (dist == 1), axis=1)
    occupied_neighbors = adj.sum(1)
    single_bonus = (hints.sum(1) == 1).astype(jnp.float32)[:, None] * 0.45
    place_score = (8.0 * correct + 0.35 * same_degree[None, :] + 0.025 * occupied_neighbors[None, :]
                   + single_bonus - 2.5 * lock_conflict[None, :] + 0.1 * anchor_support[None, :])
    place_score = jnp.where(correct > 0.99, place_score, place_score - 4.)
    place_score = place_score - 2.0 * (jnp.arange(9) == planned_card)[None, :]
    card_at_cell = jnp.all(cells[:, None, :] == pos[None, :, :], axis=-1)
    place_cell = jnp.einsum('hi,ci->hc', place_score, card_at_cell.astype(jnp.float32))
    hint_scores = jnp.concatenate((jnp.asarray([8.35, 8.32, 8.31, 8.30]), place_cell.reshape(-1)))
    hint_action = 739 + jnp.argmax(jnp.where(obs.legal_actions[739:1067], hint_scores, -1e9))
    phase = features[0, 11]
    active = features[0, 10] > 0
    action = jnp.where(phase < 2, inspect, jnp.where(phase == 2, move, hint_action))
    action = jnp.where(active, action, 0).astype(jnp.int32)
    return action, {'known': known, 'log_evidence': log_evidence, 'positions': pos, 'partner_seen': seen, 'partner_moved': partner_moved, 'planned_card': planned_card}, {'known': known, 'expected_edges': edges, 'p_solved': p_solved, 'marginal': marginal, 'observation_value': voi, 'planned_card': planned_card, 'legality_mismatch': jnp.sum((move_legality(pos, locked) != obs.legal_actions[10:739]) & active & (phase == 2))}
